entries[698] = { ["name"] = "Ritual of Summoning", ["text"] = "12% of base mana 30 yd range\nChanneled (2 min cast) 2 min cooldown\nBegins a ritual that creates a summoning portal. The summoning portal can be used by 2 party or raid members to summon a targeted party or raid member. The ritual portal requires the caster and 2 additional party or raid members to complete. In order to participate, all players must be out of combat and right-click the portal and not move until the ritual is complete." }
entries[700] = { ["name"] = "Sleep", ["text"] = "60 Mana 30 yd range\n1.5 sec cast\nPuts the enemy target to sleep for up to 20 sec. Any damage caused will awaken the target. Only one target can be asleep at a time. Unreliable on targets above level 30." }
entries[702] = { ["name"] = "Curse of Weakness", ["text"] = "10% of base mana 40 yd range\nInstant\nTarget's physical damage done is reduced by 10% for 2 min. Only one Curse per Warlock can be active on any one target." }
entries[703] = { ["name"] = "Garrote", ["text"] = "45 Energy Melee Range\nInstant\nRequires Stealth\nGarrote the enemy, silencing them for 3 sec and causing [( 111 + Attack power * ( ( 1 ) * 1 ) * 0.07) * 6] damage over 18 sec, increased by your attack power. Must be stealthed and behind the target. Awards 1 combo point." }
entries[710] = { ["name"] = "Banish", ["text"] = "8% of base mana 30 yd range\n1.5 sec cast\nBanishes the enemy target, preventing all action but making it invulnerable for up to 30 sec. Only one target can be banished at a time. Casting Banish on a banished target will cancel the spell. Only works on Demons and Elementals." }
entries[712] = { ["name"] = "Summon Succubus", ["text"] = "80% of base mana\n6 sec cast\nSummons a Succubus under the command of the Warlock. [ Soulburn : Soulburn: Instant cast. ]" }
entries[713] = { ["name"] = "Summon Incubus", ["text"] = "80% of base mana\n6 sec cast\nSummons an Incubus under the command of the Warlock. [ Soulburn : Soulburn: Instant cast. ]" }
